  CONSTRAINT "feed_ads_body_check" CHECK ((length(body) <= 500)),
  CONSTRAINT "feed_ads_cta_label_check" CHECK ((length(cta_label) <= 40)),
  CONSTRAINT "feed_ads_cta_url_check" CHECK (((cta_url = '') OR (cta_url GLOB 'https://*' OR cta_url GLOB '/*'))),
  CONSTRAINT "feed_ads_status_check" CHECK (status IN ('active', 'paused', 'removed')),
  CONSTRAINT "feed_ads_target_industry_check" CHECK ((length(target_industry) <= 100)),
  CONSTRAINT "feed_ads_title_check" CHECK (((length(title) >= 1) AND (length(title) <= 120))),
  CONSTRAINT "feed_ads_tone_check" CHECK (tone IN ('violet', 'pink', 'blue', 'green'))
);
CREATE TABLE "finance_budgets" (
  "company_id" TEXT NOT NULL,
  "fiscal_year" INTEGER NOT NULL,
  "department" TEXT NOT NULL,
  "amount" NUMERIC NOT NULL,
  "updated_by" TEXT,
  "updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY ("company_id", "fiscal_year", "department"),
  FOREIGN KEY (company_id) REFERENCES "companies"(id),
