  CONSTRAINT "finance_budgets_department_check" CHECK (((length(department) >= 1) AND (length(department) <= 60))),
  CONSTRAINT "finance_budgets_fiscal_year_check" CHECK (((fiscal_year >= 2000) AND (fiscal_year <= 2200)))
);
CREATE TABLE "finance_closing" (
