  FOREIGN KEY (company_id) REFERENCES "companies"(id),
  CONSTRAINT "finance_closing_fiscal_year_check" CHECK (((fiscal_year >= 2000) AND (fiscal_year <= 2200))),
  CONSTRAINT "finance_closing_step_check" CHECK (((step >= 1) AND (step <= 5)))
);
CREATE TABLE "finance_targets" (
  "company_id" TEXT NOT NULL,
  "fiscal_year" INTEGER NOT NULL,
  "revenue" NUMERIC,
  "profit" NUMERIC,
  "expense_cap" NUMERIC,
  "updated_by" TEXT,
  "updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY ("company_id", "fiscal_year"),
  FOREIGN KEY (company_id) REFERENCES "companies"(id),
  CONSTRAINT "finance_targets_expense_cap_check" CHECK (((expense_cap >= (0)) AND (expense_cap <= '1000000000000'))),
  CONSTRAINT "finance_targets_fiscal_year_check" CHECK (((fiscal_year >= 2000) AND (fiscal_year <= 2200))),
  CONSTRAINT "finance_targets_profit_check" CHECK ((abs(profit) <= '1000000000000')),
  CONSTRAINT "finance_targets_revenue_check" CHECK (((revenue >= (0)) AND (revenue <= '1000000000000')))
);
CREATE TABLE "free_limits" (
