  "missing" TEXT NOT NULL DEFAULT '[]' CHECK ("missing" IS NULL OR json_valid("missing")),
  "status" TEXT NOT NULL DEFAULT 'queued',
  "source" TEXT NOT NULL DEFAULT 'Web',
  "source_event" TEXT,
  "group_id" TEXT,
  "attachment_id" TEXT,
  "engine" TEXT,
  "error" TEXT,
  "lease_until" TEXT,
  "lease_id" TEXT,
  "attempts" INTEGER NOT NULL DEFAULT 0,
  "created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  "created_by" TEXT,
  "source_user" TEXT,
  "nudged_at" TEXT,
  "pages" INTEGER,
  "reply_token" TEXT,
  "target_kind" TEXT,
  "bot_message_id" TEXT,
  "decided_at" TEXT,
  "decided_by" TEXT,
  "decided_name" TEXT,
  "decided_via" TEXT,
  "decided_group" TEXT,
  "sender_name" TEXT,
  "group_name" TEXT,
