  "post_id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY ("post_id", "user_id"),
  FOREIGN KEY (post_id) REFERENCES "company_posts"(id) ON DELETE CASCADE
);
CREATE TABLE "project_inventory" (
  "company_id" TEXT NOT NULL,
  "product_id" TEXT NOT NULL,
  "project_id" TEXT NOT NULL,
  "quantity" INTEGER NOT NULL DEFAULT 0,
  "updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY ("product_id", "project_id"),
  FOREIGN KEY (company_id) REFERENCES "companies"(id),
  FOREIGN KEY (product_id) REFERENCES "entities"(id),
  FOREIGN KEY (project_id) REFERENCES "entities"(id),
  CONSTRAINT "project_inventory_quantity_check" CHECK ((quantity >= 0))
);
CREATE TABLE "project_stage_history" (
  "id" TEXT NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  "company_id" TEXT NOT NULL,
  "project_id" TEXT NOT NULL,
  "key" TEXT NOT NULL,
  "department" TEXT NOT NULL,
  "status" TEXT NOT NULL,
  "actor" TEXT,
  "created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY ("id"),
  FOREIGN KEY (company_id) REFERENCES "companies"(id),
  FOREIGN KEY (project_id) REFERENCES "entities"(id)
);
CREATE TABLE "project_stages" (
  "company_id" TEXT NOT NULL,
  "project_id" TEXT NOT NULL,
  "key" TEXT NOT NULL,
  "ordinal" INTEGER NOT NULL,
  "department" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  "english" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'pending',
  "version" INTEGER NOT NULL DEFAULT 1,
  "started_at" TEXT,
  "completed_at" TEXT,
  "updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  "updated_by" TEXT,
  PRIMARY KEY ("project_id", "key"),
  FOREIGN KEY (company_id) REFERENCES "companies"(id),
  FOREIGN KEY (project_id) REFERENCES "entities"(id),
  CONSTRAINT "project_stages_status_check" CHECK (status IN ('pending', 'progress', 'review', 'done'))
);
CREATE TABLE "promos" (
  "id" TEXT NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  "title" TEXT NOT NULL,
  "body" TEXT NOT NULL DEFAULT '',
  "cta_label" TEXT NOT NULL DEFAULT '',
  "cta_url" TEXT NOT NULL DEFAULT '',
  "tone" TEXT NOT NULL DEFAULT 'violet',
  "active" INTEGER NOT NULL DEFAULT 1 CHECK ("active" IN (0,1)),
  "starts_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  "ends_at" TEXT,
  "ordinal" INTEGER NOT NULL DEFAULT 0,
  "created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  "placement" TEXT NOT NULL DEFAULT 'landing',
  "media_url" TEXT NOT NULL DEFAULT '',
  "media_type" TEXT NOT NULL DEFAULT '',
  PRIMARY KEY ("id"),
  CONSTRAINT "promos_body_check" CHECK ((length(body) <= 500)),
  CONSTRAINT "promos_cta_label_check" CHECK ((length(cta_label) <= 40)),
  CONSTRAINT "promos_cta_url_check" CHECK (((cta_url = '') OR (cta_url GLOB 'https://*' OR cta_url GLOB '/*'))),
  CONSTRAINT "promos_media_type_check" CHECK (media_type IN ('', 'image', 'video')),
  CONSTRAINT "promos_media_url_check" CHECK (((media_url = '') OR (media_url GLOB 'https://*'))),
  CONSTRAINT "promos_placement_check" CHECK (placement IN ('landing', 'feed', 'both', 'billing')),
  CONSTRAINT "promos_title_check" CHECK (((length(title) >= 1) AND (length(title) <= 120))),
  CONSTRAINT "promos_tone_check" CHECK (tone IN ('violet', 'pink', 'blue', 'green'))
);
CREATE TABLE "share_attempts" (
  "id" INTEGER PRIMARY KEY AUTOINCREMENT,
  "token_hash" TEXT NOT NULL,
  "client_hash" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE TABLE "shop_items" (
  "id" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "price_coins" INTEGER NOT NULL,
  "period" TEXT NOT NULL DEFAULT 'once',
  "active" INTEGER NOT NULL DEFAULT 1 CHECK ("active" IN (0,1)),
  "ordinal" INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY ("id"),
  CONSTRAINT "shop_items_kind_check" CHECK (kind IN ('character', 'theme', 'system')),
  CONSTRAINT "shop_items_period_check" CHECK (period IN ('once', 'month')),
  CONSTRAINT "shop_items_price_coins_check" CHECK ((price_coins >= 0))
);
CREATE TABLE "stock_movements" (
  "id" TEXT NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  "company_id" TEXT NOT NULL,
  "product_id" TEXT NOT NULL,
  "type" TEXT NOT NULL,
  "quantity" INTEGER NOT NULL,
  "reference" TEXT NOT NULL,
  "notes" TEXT,
  "created_by" TEXT,
  "created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY ("id"),
  UNIQUE (company_id, product_id, reference),
  FOREIGN KEY (company_id) REFERENCES "companies"(id),
  FOREIGN KEY (product_id) REFERENCES "entities"(id),
  CONSTRAINT "stock_movements_quantity_check" CHECK ((quantity > 0)),
  CONSTRAINT "stock_movements_type_check" CHECK (type IN ('in', 'out'))
);
CREATE TABLE "stock_transfers" (
  "id" TEXT NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  "company_id" TEXT NOT NULL,
  "product_id" TEXT NOT NULL,
  "from_project" TEXT,
  "to_project" TEXT,
  "quantity" INTEGER NOT NULL,
  "reason" TEXT NOT NULL,
  "reference" TEXT NOT NULL,
  "created_by" TEXT,
  "created_name" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY ("id"),
  UNIQUE (company_id, reference),
  FOREIGN KEY (company_id) REFERENCES "companies"(id),
  FOREIGN KEY (from_project) REFERENCES "entities"(id),
  FOREIGN KEY (product_id) REFERENCES "entities"(id),
  FOREIGN KEY (to_project) REFERENCES "entities"(id),
  CONSTRAINT "stock_transfers_check" CHECK ((from_project IS DISTINCT FROM to_project)),
  CONSTRAINT "stock_transfers_quantity_check" CHECK ((quantity > 0))
);
CREATE TABLE "subscriptions" (
  "company_id" TEXT NOT NULL,
  "plan" TEXT NOT NULL DEFAULT 'free',
  "cycle" TEXT NOT NULL DEFAULT 'monthly',
  "status" TEXT NOT NULL DEFAULT 'active',
  "trial_ends_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now','+14 days')),
  "current_period_end" TEXT,
  "addons" TEXT NOT NULL DEFAULT '[]' CHECK ("addons" IS NULL OR json_valid("addons")),
  "extra_users" INTEGER NOT NULL DEFAULT 0,
  "updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY ("company_id"),
  FOREIGN KEY (company_id) REFERENCES "companies"(id),
  FOREIGN KEY (plan) REFERENCES "plans"(id),
  CONSTRAINT "subscriptions_cycle_check" CHECK (cycle IN ('monthly', 'yearly')),
  CONSTRAINT "subscriptions_extra_users_check" CHECK (((extra_users >= 0) AND (extra_users <= 1000))),
  CONSTRAINT "subscriptions_status_check" CHECK (status IN ('trial', 'active', 'past_due', 'cancelled'))
);
CREATE TABLE "support_access" (
  "id" TEXT NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  "company_id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "admin_email" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "started_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  "expires_at" TEXT NOT NULL,
  "ended_at" TEXT,
  "ended_by" TEXT,
  PRIMARY KEY ("id"),
  FOREIGN KEY (company_id) REFERENCES "companies"(id) ON DELETE CASCADE,
  CONSTRAINT "support_access_reason_check" CHECK (((length(reason) >= 5) AND (length(reason) <= 300)))
);
CREATE TABLE "support_messages" (
  "id" TEXT NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  "company_id" TEXT NOT NULL,
  "sender" TEXT NOT NULL,
  "user_id" TEXT,
  "name" TEXT NOT NULL,
  "body" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY ("id"),
  FOREIGN KEY (company_id) REFERENCES "companies"(id),
  CONSTRAINT "support_messages_body_check" CHECK (((length(body) >= 1) AND (length(body) <= 4000))),
  CONSTRAINT "support_messages_sender_check" CHECK (sender IN ('customer', 'admin'))
);
CREATE TABLE "support_threads" (
  "company_id" TEXT NOT NULL,
  "unread_admin" INTEGER NOT NULL DEFAULT 0,
  "unread_customer" INTEGER NOT NULL DEFAULT 0,
  "status" TEXT NOT NULL DEFAULT 'open',
  "updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY ("company_id"),
  FOREIGN KEY (company_id) REFERENCES "companies"(id),
  CONSTRAINT "support_threads_status_check" CHECK (status IN ('open', 'closed'))
);
CREATE TABLE "trial_limits" (
  "resource" TEXT NOT NULL,
  "amount" INTEGER NOT NULL,
  "label" TEXT NOT NULL,
  PRIMARY KEY ("resource"),
  CONSTRAINT "trial_limits_amount_check" CHECK ((amount >= 0))
);
CREATE TABLE "user_notes" (
  "id" TEXT NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  "company_id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "day" TEXT NOT NULL,
  "body" TEXT NOT NULL DEFAULT '',
  "items" TEXT NOT NULL DEFAULT '[]' CHECK ("items" IS NULL OR json_valid("items")),
  "updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY ("id"),
  UNIQUE (company_id, user_id, day),
  FOREIGN KEY (company_id) REFERENCES "companies"(id),
  CONSTRAINT "user_notes_body_check" CHECK ((length(body) <= 4000)),
  CONSTRAINT "user_notes_items_check" CHECK (((json_type(items) = 'array') AND (json_array_length(items) <= 30)))
);
CREATE TABLE "user_profiles" (
  "user_id" TEXT NOT NULL,
  "avatar_at" TEXT,
  "updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY ("user_id")
);
CREATE TABLE "wht_certificates" (
  "id" TEXT NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  "company_id" TEXT NOT NULL,
  "entity_id" TEXT NOT NULL,
  "year" INTEGER NOT NULL,
  "seq" INTEGER NOT NULL,
  "form" TEXT NOT NULL,
  "payee" TEXT NOT NULL,
  "tax_id" TEXT,
  "base" NUMERIC NOT NULL,
  "rate" NUMERIC NOT NULL,
  "amount" NUMERIC NOT NULL,
  "paid_on" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY ("id"),
  UNIQUE (company_id, year, seq),
  UNIQUE (entity_id),
  FOREIGN KEY (company_id) REFERENCES "companies"(id),
  FOREIGN KEY (entity_id) REFERENCES "entities"(id),
  CONSTRAINT "wht_certificates_form_check" CHECK (form IN ('ภ.ง.ด.3', 'ภ.ง.ด.53'))
);

CREATE INDEX IF NOT EXISTS "ai_usage_company" ON "ai_usage" (company_id, created_at DESC);
CREATE INDEX IF NOT EXISTS "attachments_ingestion" ON "attachments" (ingestion_id) WHERE (ingestion_id IS NOT NULL);
CREATE INDEX IF NOT EXISTS "audit_company" ON "audit_events" (company_id, created_at DESC);
CREATE INDEX IF NOT EXISTS "b2b_cards_deal" ON "b2b_cards" (deal_id, created_at);
CREATE INDEX IF NOT EXISTS "b2b_deals_thread" ON "b2b_deals" (thread_id, created_at DESC);
CREATE INDEX IF NOT EXISTS "b2b_messages_thread" ON "b2b_messages" (thread_id, created_at DESC);
CREATE INDEX IF NOT EXISTS "b2b_threads_a" ON "b2b_threads" (company_a, last_at DESC);
CREATE INDEX IF NOT EXISTS "b2b_threads_b" ON "b2b_threads" (company_b, last_at DESC);
CREATE INDEX IF NOT EXISTS "coin_ledger_company" ON "coin_ledger" (company_id, created_at);
CREATE INDEX IF NOT EXISTS "company_posts_company" ON "company_posts" (company_id, created_at DESC);
CREATE INDEX IF NOT EXISTS "company_posts_feed" ON "company_posts" (created_at DESC) WHERE (archived_at IS NULL);
CREATE INDEX IF NOT EXISTS "entities_company_kind" ON "entities" (company_id, kind, updated_at DESC);
CREATE INDEX IF NOT EXISTS "entities_department" ON "entities" (company_id, department) WHERE (archived_at IS NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "product_sku" ON "entities" (company_id, (json_extract(data,'$.sku'))) WHERE ((kind = 'products') AND (archived_at IS NULL));
CREATE INDEX IF NOT EXISTS "feed_ads_live" ON "feed_ads" (ends_at) WHERE (status = 'active');
CREATE INDEX IF NOT EXISTS "ingestion_queue" ON "ingestions" (status, created_at);
CREATE INDEX IF NOT EXISTS "ingestions_bot_message" ON "ingestions" (group_id, bot_message_id) WHERE (bot_message_id IS NOT NULL);
CREATE INDEX IF NOT EXISTS "ingestions_group_recent" ON "ingestions" (company_id, group_id, created_at DESC) WHERE (group_id IS NOT NULL);
CREATE INDEX IF NOT EXISTS "journal_lines_entry" ON "journal_lines" (entry_id);
CREATE INDEX IF NOT EXISTS "memberships_seen_idx" ON "memberships" (company_id, last_seen_at);
CREATE INDEX IF NOT EXISTS "messages_channel" ON "messages" (company_id, channel, created_at DESC);
CREATE INDEX IF NOT EXISTS "plan_grants_company" ON "plan_grants" (company_id, created_at DESC);
CREATE INDEX IF NOT EXISTS "plan_grants_recent" ON "plan_grants" (created_at DESC);
CREATE INDEX IF NOT EXISTS "post_comments_post" ON "post_comments" (post_id, created_at);
CREATE INDEX IF NOT EXISTS "post_proposals_company" ON "post_proposals" (company_id, created_at DESC);
CREATE INDEX IF NOT EXISTS "post_saves_user" ON "post_saves" (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS "share_attempts_client" ON "share_attempts" (client_hash, created_at DESC);
CREATE INDEX IF NOT EXISTS "share_attempts_lookup" ON "share_attempts" (token_hash, created_at DESC);
CREATE INDEX IF NOT EXISTS "support_access_company" ON "support_access" (company_id, started_at DESC);
CREATE INDEX IF NOT EXISTS "support_access_open" ON "support_access" (user_id, company_id) WHERE (ended_at IS NULL);
CREATE INDEX IF NOT EXISTS "support_messages_company" ON "support_messages" (company_id, created_at);
CREATE INDEX IF NOT EXISTS "user_notes_owner" ON "user_notes" (company_id, user_id, day DESC);
